 register({name:'set_railway_ambience',title:'ควบคุมเสียงบรรยากาศ',description:'Enable or mute wind, water and rain sounds, or set their independent volume. First playback requires the sound button or B key.',inputSchema:{type:'object',properties:{enabled:{type:'boolean'},volume:{type:'number',minimum:0,maximum:1}},minProperties:1,additionalProperties:false},annotations:{readOnlyHint:false},execute:async input=>{if(!input||!Object.keys(input).length||Object.keys(input).some(k=>!['enabled','volume'].includes(k))||('enabled' in input&&typeof input.enabled!=='boolean')||('volume' in input&&(!Number.isFinite(input.volume)||input.volume<0||input.volume>1)))throw new Error('Invalid ambience controls');if('volume' in input)ambience.setVolume(input.volume);return 'enabled' in input?await ambience.setEnabled(input.enabled):ambience.state();}});
 register({name:'set_railway_train_audio',title:'ควบคุมเสียงรถไฟ',description:'Enable or mute train wheels, rail joints and carriage creaks independently of wind, rain and music. First playback requires a user gesture.',inputSchema:{type:'object',properties:{enabled:{type:'boolean'},volume:{type:'number',minimum:0,maximum:1}},minProperties:1,additionalProperties:false},annotations:{readOnlyHint:false},execute:async input=>{if(!input||!Object.keys(input).length||Object.keys(input).some(k=>!['enabled','volume'].includes(k))||('enabled' in input&&typeof input.enabled!=='boolean')||('volume' in input&&(!Number.isFinite(input.volume)||input.volume<0||input.volume>1)))throw new Error('Invalid train sound controls');if('volume' in input)ambience.setTrainVolume(input.volume);return 'enabled' in input?await ambience.setTrainEnabled(input.enabled):ambience.state();}});
 register({name:'set_railway_clock',title:'ควบคุมเวลาไทย',description:'Sync light continuously to real GMT+7 time, or freeze/unfreeze the currently visible light. Manual day/evening/night selection disables sync and lock.',inputSchema:{type:'object',properties:{sync:{type:'boolean'},locked:{type:'boolean'}},minProperties:1,additionalProperties:false},annotations:{readOnlyHint:false},execute:async input=>{if(!input||!Object.keys(input).length||Object.keys(input).some(k=>!['sync','locked'].includes(k))||Object.values(input).some(v=>typeof v!=='boolean'))throw new Error('Invalid clock controls');if('sync' in input)setTimeSync(input.sync);if('locked' in input)setTimeLock(input.locked);return {sync:timeControl.sync,locked:timeControl.locked};}});
 register({name:'set_railway_rain',title:'เปิดหรือปิดฝน',description:'Fade gentle rain, glass droplets, sea ripples and ambient rain sound in or out.',inputSchema:{type:'object',properties:{enabled:{type:'boolean'}},required:['enabled'],additionalProperties:false},annotations:{readOnlyHint:false},execute:async input=>{if(!input||typeof input.enabled!=='boolean'||Object.keys(input).some(k=>k!=='enabled'))throw new Error('Invalid rain control');return setRain(input.enabled);}});
 register({name:'set_railway_motion',title:'ควบคุมทิศทางรถไฟ',description:'Stop, travel forward, or reverse smoothly. A reversal brakes to zero before accelerating in the other direction.',inputSchema:{type:'object',properties:{direction:{type:'string',enum:['stop','forward','reverse']}},required:['direction'],additionalProperties:false},annotations:{readOnlyHint:false},execute:async input=>{if(!input||!['stop','forward','reverse'].includes(input.direction)||Object.keys(input).some(k=>k!=='direction'))throw new Error('Invalid train direction');return setTrainDirection(input.direction);}});
