function resumeRememberedAudio(){if(!started||!waitingAudioGesture)return;waitingAudioGesture=false;if(restoredSettings.musicEnabled)music.setEnabled(true,{gesture:true});if(restoredSettings.ambienceEnabled)ambience.setEnabled(true,{gesture:true});if(restoredSettings.trainEnabled)ambience.setTrainEnabled(true,{gesture:true});}$('#control-open').addEventListener('click',resumeRememberedAudio);window.addEventListener('pointerdown',resumeRememberedAudio,{once:true,capture:true});window.addEventListener('keydown',resumeRememberedAudio,{once:true,capture:true});for(const audio of [music,ambience]){const previous=audio.onChange;audio.onChange=state=>{previous(state);persistSettings();};}window.addEventListener('pagehide',persistSettings);settingsReady=true;updateWeatherUI();startUI.show({saved:checkpoint,quality:qualityName,sound:restoredSettings.ambienceEnabled||restoredSettings.trainEnabled||restoredSettings.musicEnabled});
